MonarchFormField("Renewal date") {
    HStack {
        if let date = renewal {
            DatePicker("Renewal date", selection: Binding(get: { date }, set: { renewal = $0 }), displayedComponents: .date)
                .labelsHidden()
            MonarchButton("Clear date", variant: .ghost, size: .sm) { renewal = nil }
        } else {
            MonarchButton("Set date", systemImage: "calendar", size: .sm) { renewal = .now }
        }
    }
}
